def even_odd_count(num: int) -> tuple[int, int]:
    """Return a tuple with the number of even and odd digits in an integer.

    The sign of the integer is ignored. Zero counts as one even digit.

    Examples:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    n = abs(num)
    if n == 0:
        return (1, 0)

    even, odd = 0, 0
    while n:
        digit = n % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        n //= 10

    return (even, odd)
